def render(template, values):
    """The template with its fields filled from `values`. See TASK.md."""
    result = []
    i = 0

    while i < len(template):
        if template[i] == '{':
            # Check for literal {{
            if i + 1 < len(template) and template[i + 1] == '{':
                result.append('{')
                i += 2
                continue

            # Find closing }
            close_idx = template.find('}', i + 1)
            if close_idx == -1:
                raise ValueError("unclosed brace")

            # Extract field content
            field_content = template[i + 1:close_idx]

            # Check for { inside field
            if '{' in field_content:
                raise ValueError("brace inside field")

            # Parse field: path or path|default
            if '|' in field_content:
                path_part, default_part = field_content.split('|', 1)
            else:
                path_part = field_content
                default_part = None

            # Strip whitespace from path
            path_part = path_part.strip()

            # Check for empty field
            if not path_part:
                raise ValueError("empty field")

            # Parse path into names
            names = path_part.split('.')

            # Validate path: each name must be valid (letters, digits, underscores)
            for name in names:
                if not name:  # Empty name (like in a..b)
                    raise ValueError("invalid path")
                if not all(c.isalnum() or c == '_' for c in name):
                    raise ValueError("invalid path")

            # Lookup the value
            current = values
            found = True

            for name in names:
                if isinstance(current, dict):
                    if name in current:
                        current = current[name]
                    else:
                        found = False
                        break
                elif isinstance(current, (list, tuple)):
                    if name.isdigit():
                        try:
                            current = current[int(name)]
                        except IndexError:
                            found = False
                            break
                    else:
                        found = False
                        break
                else:
                    found = False
                    break

            if not found:
                if default_part is not None:
                    result.append(default_part)
                else:
                    raise KeyError(path_part)
            else:
                # Convert value to string
                if current is None:
                    result.append('')
                elif isinstance(current, bool):
                    result.append('true' if current else 'false')
                else:
                    result.append(str(current))

            i = close_idx + 1
        elif template[i] == '}':
            # Check for literal }}
            if i + 1 < len(template) and template[i + 1] == '}':
                result.append('}')
                i += 2
                continue
            else:
                raise ValueError("unmatched closing brace")
        else:
            result.append(template[i])
            i += 1

    return ''.join(result)
